files.infra/main.tf:
resource "aws_db_instance" "staging" {
  identifier     = "shop-staging"
  engine         = "postgres"
  instance_class = "db.r6g.4xlarge"
}

resource "aws_s3_bucket" "logs" {
  bucket = "shop-logs"
}

resource "aws_instance" "dev_worker" {
  ami           = "ami-0abcdef1234567890"
  instance_type = "m5.2xlarge"
  tags = {
    Environment = "dev"
  }
}
